export function faceSVG(f,key=''){
 const id='g'+f.id+key;
 const eyes=f.id==='calm'?'<path d="M22 30q6 7 12 0m12 0q6 7 12 0" fill="none" stroke="#354448" stroke-width="3" stroke-linecap="round"/>':'<ellipse cx="28" cy="29" rx="8" ry="10" fill="#fffbea"/><ellipse cx="52" cy="29" rx="8" ry="10" fill="#fffbea"/><ellipse cx="29" cy="30" rx="3.8" ry="6" fill="#303b45"/><ellipse cx="53" cy="30" rx="3.8" ry="6" fill="#303b45"/><circle cx="28" cy="27" r="1.3" fill="white"/><circle cx="52" cy="27" r="1.3" fill="white"/>';
 const mouth=f.id==='amazed'?'<ellipse cx="40" cy="53" rx="6" ry="8" fill="#354448"/>':f.id==='confused'?'<path d="M33 54q7-8 14-2M19 16l15 5M47 18l13-5" fill="none" stroke="#354448" stroke-width="2.5" stroke-linecap="round"/>':f.id==='neutral'?'<path d="M33 53h14" stroke="#354448" stroke-width="2.7" stroke-linecap="round"/>':'<path d="M29 49q11 14 22 0" fill="none" stroke="#354448" stroke-width="2.7" stroke-linecap="round"/>';
 return `<svg viewBox="0 0 80 80" aria-hidden="true"><defs><radialGradient id="${id}" cx="30%" cy="25%" r="75%"><stop offset="0" stop-color="${f.light}"/><stop offset=".55" stop-color="${f.color}"/><stop offset="1" stop-color="${f.color}"/></radialGradient></defs><circle cx="40" cy="40" r="37" fill="url(#${id})"/><ellipse cx="27" cy="14" rx="11" ry="4" fill="white" opacity=".35" transform="rotate(-24 27 14)"/>${eyes}${mouth}</svg>`;
}
